//! Core ISA description traits.
//!
//! Per-ISA crates implement [`Architecture`] for their concrete ISA type.
//! Trait surface follows `gen-isa/docs/design.md` Sec 2.

#![no_std]

pub mod address;
pub mod endian;
pub mod format;
pub mod register;

/// Pure ISA description: opcodes, encoding, decoding, disassembly.
///
/// No ABI, no codegen, no IR awareness. ABI lives in `sw-target-core`;
/// codegen in `sw-codegen-core`; IR in `sw-tir`.
pub trait Architecture {
    type Opcode: Copy + core::fmt::Debug + Eq + Mnemonic;
    type Register: Copy + core::fmt::Debug + Eq + register::RegisterId;
    type Instruction: Copy + core::fmt::Debug;
    type Address: address::AddressType;
    type Format: format::FormatInfo;

    const NAME: &'static str;
    const ENDIAN: endian::Endian;
    const ADDRESS_UNIT: address::AddressUnit;
    const WORD_BITS: u32;
    const MAX_INSTR_BYTES: usize;
    const MIN_INSTR_BYTES: usize;

    fn decode(
        bytes: &[u8],
        pc: Self::Address,
    ) -> Result<(Self::Instruction, usize), DecodeError>;

    fn encode(insn: &Self::Instruction, out: &mut [u8]) -> Result<usize, EncodeError>;

    fn disassemble(
        insn: &Self::Instruction,
        w: &mut dyn core::fmt::Write,
    ) -> core::fmt::Result;
}

/// Mnemonic accessor for opcode types.
pub trait Mnemonic {
    fn mnemonic(&self) -> &'static str;
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum DecodeError {
    Truncated,
    Invalid,
}

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum EncodeError {
    BufferTooSmall,
    InvalidOperands,
}

//! Address-arithmetic primitives.
//!
//! [`AddressUnit`] tells the IR and codegen how the ISA addresses memory.
//! Word-addressed ISAs (IBM 1130) and byte-addressed ISAs (most others)
//! must not be silently mixed; per-ISA newtype wrappers around `AddressType`
//! enforce this at compile time.

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum AddressUnit {
    Byte,
    Word16,
    Word24,
    Word32,
}

impl AddressUnit {
    /// Bytes per address-unit step.
    pub const fn byte_size(self) -> usize {
        match self {
            AddressUnit::Byte => 1,
            AddressUnit::Word16 => 2,
            AddressUnit::Word24 => 3,
            AddressUnit::Word32 => 4,
        }
    }
}

/// Per-ISA address type. Newtype around an integer; arithmetic is in
/// address-units, not bytes.
pub trait AddressType: Copy + Ord {
    fn to_u64(self) -> u64;
    fn from_u64(v: u64) -> Self;
    /// Step `n` address-units forward (or backward if `n` is negative).
    fn step(self, n: i64) -> Self;
}

//! Endianness declaration.

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum Endian {
    Big,
    Little,
    /// COR24-style: instruction bytes are a flat stream; multi-byte
    /// fields are positional rather than endian-interpreted.
    ByteStream,
}

//! Instruction format info.
//!
//! Length-only ISAs (COR24, CDP1802, IBM 1130) can use [`Length`].
//! Multi-format ISAs (S/370 RR/RX/RS/SI/SS) define their own enum and
//! implement [`FormatInfo`] for it.

pub trait FormatInfo: Copy + core::fmt::Debug {
    fn size_bytes(&self) -> usize;
}

/// Default format type for ISAs whose format is just instruction length.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum Length {
    B1,
    B2,
    B3,
    B4,
    B6,
    B8,
}

impl FormatInfo for Length {
    fn size_bytes(&self) -> usize {
        match self {
            Length::B1 => 1,
            Length::B2 => 2,
            Length::B3 => 3,
            Length::B4 => 4,
            Length::B6 => 6,
            Length::B8 => 8,
        }
    }
}

//! Register identification.
//!
//! Per-ISA crates define a concrete `Register` type (enum or newtype)
//! and implement [`RegisterId`] for it.

pub trait RegisterId: Copy {
    fn index(self) -> u32;
    fn name(self) -> &'static str;
}

use sw_isa_core::address::AddressUnit;
use sw_isa_core::endian::Endian;
use sw_isa_core::format::{FormatInfo, Length};

#[test]
fn length_size_bytes() {
    assert_eq!(Length::B1.size_bytes(), 1);
    assert_eq!(Length::B2.size_bytes(), 2);
    assert_eq!(Length::B4.size_bytes(), 4);
    assert_eq!(Length::B6.size_bytes(), 6);
}

#[test]
fn address_unit_byte_size() {
    assert_eq!(AddressUnit::Byte.byte_size(), 1);
    assert_eq!(AddressUnit::Word16.byte_size(), 2);
    assert_eq!(AddressUnit::Word24.byte_size(), 3);
    assert_eq!(AddressUnit::Word32.byte_size(), 4);
}

#[test]
fn endian_variants_compile() {
    let _ = [Endian::Big, Endian::Little, Endian::ByteStream];
}

