//! Target-Independent Representation (TIR).
//!
//! SSA with block parameters. Frontends emit TIR; codegens consume it.
//! Trait surface follows `gen-isa/docs/design.md` Sec 4 and decisions D2/D3.
//!
//! No `sw-isa-core` dep -- TIR is innocent of ISA specifics. ISA-specific
//! intrinsics go through [`Op::Intrinsic`] and are lowered per-target by
//! the codegen backend.

use core::fmt;

// ---------- Identifiers ----------

#[derive(Copy, Clone, Debug, Eq, PartialEq, Hash)]
pub struct ValueId(pub u32);

#[derive(Copy, Clone, Debug, Eq, PartialEq, Hash)]
pub struct BlockId(pub u32);

#[derive(Copy, Clone, Debug, Eq, PartialEq, Hash)]
pub struct StructId(pub u32);

#[derive(Clone, Debug, Eq, PartialEq, Hash)]
pub struct Symbol(pub String);

// ---------- Types ----------

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Type {
    I1,
    I8,
    I16,
    I32,
    I64,
    Ptr(Box<Type>),
    Array(Box<Type>, u32),
    Struct(StructId),
    Void,
}

// ---------- Comparison predicates ----------

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum ICmp {
    Eq,
    Ne,
    Slt,
    Sle,
    Sgt,
    Sge,
    Ult,
    Ule,
    Ugt,
    Uge,
}

// ---------- Operations ----------

#[derive(Clone, Debug)]
pub enum Op {
    Add(ValueId, ValueId),
    Sub(ValueId, ValueId),
    Mul(ValueId, ValueId),
    SDiv(ValueId, ValueId),
    UDiv(ValueId, ValueId),
    SRem(ValueId, ValueId),
    URem(ValueId, ValueId),
    And(ValueId, ValueId),
    Or(ValueId, ValueId),
    Xor(ValueId, ValueId),
    Shl(ValueId, ValueId),
    Shr(ValueId, ValueId),
    AShr(ValueId, ValueId),
    Load { addr: ValueId, ty: Type },
    Store { addr: ValueId, val: ValueId },
    Alloca { ty: Type, count: ValueId },
    Call { callee: ValueId, args: Vec<ValueId> },
    SExt(ValueId, Type),
    ZExt(ValueId, Type),
    Trunc(ValueId, Type),
    Icmp { pred: ICmp, lhs: ValueId, rhs: ValueId },
    AddrOf(Symbol),
    StructIndex { base: ValueId, field: u32 },
    ArrayIndex { base: ValueId, idx: ValueId, elem_size: u32 },
    Intrinsic { name: &'static str, args: Vec<ValueId> },
}

// ---------- Terminators ----------

#[derive(Clone, Debug)]
pub enum Terminator {
    Return(Option<ValueId>),
    Branch(BlockId, Vec<ValueId>),
    CondBranch {
        cond: ValueId,
        t: BlockId,
        t_args: Vec<ValueId>,
        f: BlockId,
        f_args: Vec<ValueId>,
    },
    Unreachable,
}

// ---------- Instructions and blocks ----------

#[derive(Clone, Debug)]
pub struct Instr {
    pub result: Option<ValueId>,
    pub op: Op,
    pub ty: Type,
}

#[derive(Clone, Debug)]
pub struct Block {
    pub label: BlockId,
    pub params: Vec<ValueId>,
    pub instrs: Vec<Instr>,
    pub terminator: Terminator,
}

// ---------- Functions and modules ----------

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum Linkage {
    Internal,
    External,
}

#[derive(Clone, Debug)]
pub struct FnSig {
    pub params: Vec<Type>,
    pub ret: Type,
}

#[derive(Clone, Debug)]
pub struct Local {
    pub id: ValueId,
    pub ty: Type,
}

#[derive(Clone, Debug)]
pub struct Function {
    pub name: String,
    pub linkage: Linkage,
    pub signature: FnSig,
    pub blocks: Vec<Block>,
    pub locals: Vec<Local>,
}

#[derive(Clone, Debug)]
pub struct Global {
    pub name: String,
    pub ty: Type,
    pub linkage: Linkage,
}

#[derive(Clone, Debug, Default)]
pub struct Module {
    pub name: String,
    pub functions: Vec<Function>,
    pub globals: Vec<Global>,
}

impl Module {
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            functions: Vec::new(),
            globals: Vec::new(),
        }
    }

    /// Placeholder text representation. The real pretty-printer is
    /// authored alongside the parser in a later saga step.
    pub fn to_text(&self) -> String {
        format!(
            "; module {}\n; {} functions, {} globals\n",
            self.name,
            self.functions.len(),
            self.globals.len(),
        )
    }
}

// ---------- IR construction ----------

/// IR construction helper.
///
/// Per `gen-isa/docs/decisions.md` D3, supports both alloca-based naive
/// emission (frontends use `Alloca` + `Load`/`Store`; `mem2reg` cleans up)
/// and direct-SSA emission (frontends produce SSA values directly).
#[derive(Debug, Default)]
pub struct IRBuilder {
    next_value: u32,
    next_block: u32,
}

impl IRBuilder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn fresh_value(&mut self) -> ValueId {
        let id = self.next_value;
        self.next_value += 1;
        ValueId(id)
    }

    pub fn fresh_block(&mut self) -> BlockId {
        let id = self.next_block;
        self.next_block += 1;
        BlockId(id)
    }
}

// ---------- Parser stub ----------

#[derive(Debug, Eq, PartialEq)]
pub enum ParseError {
    NotImplemented,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::NotImplemented => f.write_str("TIR text-format parser not yet implemented"),
        }
    }
}

impl core::error::Error for ParseError {}

/// Parse a TIR text-format source into a [`Module`]. Stub for now; the
/// real parser lands in a later saga step alongside the pretty-printer.
pub fn parse_module(_src: &str) -> Result<Module, ParseError> {
    Err(ParseError::NotImplemented)
}

