//! Target-independent TIR optimisation passes.
//!
//! Each pass is a `fn(&mut Module) -> bool` (returns whether changes were
//! made). Passes are composed via [`PassDriver`]. No target awareness.
//! Trait surface follows `gen-isa/docs/design.md` Sec 5.

use sw_tir::Module;

pub mod constfold;
pub mod dce;
pub mod mem2reg;

/// A single optimisation pass.
pub trait Pass {
    fn name(&self) -> &'static str;
    /// Run the pass. Return `true` if the module changed.
    fn run(&mut self, m: &mut Module) -> bool;
}

/// Compose passes; run them to a fixed point.
#[derive(Default)]
pub struct PassDriver {
    passes: Vec<Box<dyn Pass>>,
    max_iterations: u32,
}

impl PassDriver {
    pub fn new() -> Self {
        Self {
            passes: Vec::new(),
            max_iterations: 16,
        }
    }

    pub fn with_max_iterations(mut self, n: u32) -> Self {
        self.max_iterations = n;
        self
    }

    pub fn add(mut self, pass: Box<dyn Pass>) -> Self {
        self.passes.push(pass);
        self
    }

    /// Run all passes repeatedly until none reports changes, or until
    /// `max_iterations` is reached.
    pub fn run(&mut self, m: &mut Module) {
        for _ in 0..self.max_iterations {
            let mut changed = false;
            for pass in &mut self.passes {
                if pass.run(m) {
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
    }

    pub fn pass_count(&self) -> usize {
        self.passes.len()
    }
}

