    pub size_bytes: usize,
    #[serde(default)]
    pub discriminator: Option<Discriminator>,
    #[serde(rename = "field", default)]
    pub fields: Vec<Field>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Discriminator {
    pub offset: u32,
    pub width: u32,
