1	//! Orchestration: turn a [`ScaffoldRequest`] into files on a [`Filesystem`].
2	
3	use crate::emit;
4	use crate::fs::Filesystem;
5	use crate::spec::Spec;
6	use crate::templates::{Context, CrateRole, crate_name, files};
7	use std::path::{Path, PathBuf};
8	use thiserror::Error;
9	
10	/// Inputs to the scaffolder.
11	#[derive(Debug)]
12	pub struct ScaffoldRequest {
13	    /// Lowercase slug used in crate names: `sw-{slug}-isa`, etc.
14	    pub slug: String,
15	    /// Human-readable name, e.g. `"IBM 1130"`.
16	    pub display_name: String,
17	    /// Rust type name (PascalCase), e.g. `"Ibm1130"`.
18	    pub type_name: String,
19	    /// Output directory; the five crate dirs are created as children.
20	    pub out_dir: PathBuf,
21	    /// Path prefix for `sw-langtools` framework deps. Default
22	    /// `"../../sw-langtools"` assumes `--out` is a sibling of
23	    /// `~/github/sw-langtools`.
24	    pub framework_path: String,
25	    /// Overwrite existing files if any.
26	    pub force: bool,
27	    /// Optional ISA spec; when provided, the `-isa` crate's mechanical
28	    /// modules (`opcode.rs`, `register.rs`, `encode.rs`, `decode.rs`,
29	    /// `branch.rs`, `lib.rs`, `tests/roundtrip.rs`) are emitted from it.
30	    pub spec: Option<Spec>,
31	}
32	
33	#[derive(Debug, Error)]
34	pub enum ScaffoldError {
35	    #[error("output directory does not exist: {0}")]
36	    OutDirMissing(PathBuf),
37	    #[error("file already exists (use --force to overwrite): {0}")]
38	    AlreadyExists(PathBuf),
39	    #[error("invalid slug: {0} (must be lowercase ASCII letters, digits, and '-')")]
40	    InvalidSlug(String),
41	    #[error("invalid type name: {0} (must be a Rust identifier)")]
42	    InvalidTypeName(String),
43	    #[error("io: {0}")]
44	    Io(#[from] std::io::Error),
45	}
46	
47	fn validate_slug(s: &str) -> Result<(), ScaffoldError> {
48	    if s.is_empty()
49	        || !s
50	            .chars()
51	            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
52	        || s.starts_with('-')
53	        || s.ends_with('-')
54	    {
55	        return Err(ScaffoldError::InvalidSlug(s.to_string()));
56	    }
57	    Ok(())
58	}
59	
60	fn validate_type_name(s: &str) -> Result<(), ScaffoldError> {
61	    let mut chars = s.chars();
62	    let first = chars.next();
63	    let valid_first = matches!(first, Some(c) if c.is_ascii_alphabetic() || c == '_');
64	    let valid_rest = chars.all(|c| c.is_ascii_alphanumeric() || c == '_');
65	    if !valid_first || !valid_rest {
66	        return Err(ScaffoldError::InvalidTypeName(s.to_string()));
67	    }
68	    Ok(())
69	}
70	
71	/// Scaffold the five-crate quintet for an ISA.
72	///
73	/// Returns the list of files written, in deterministic order (sorted by
74	/// crate then by file).
75	pub fn scaffold(
76	    req: &ScaffoldRequest,
77	    fs: &mut dyn Filesystem,
78	) -> Result<Vec<PathBuf>, ScaffoldError> {
79	    validate_slug(&req.slug)?;
80	    validate_type_name(&req.type_name)?;
81	
82	    if !fs.exists(&req.out_dir) {
83	        return Err(ScaffoldError::OutDirMissing(req.out_dir.clone()));
84	    }
85	
86	    let mut written = Vec::new();
87	    for role in CrateRole::ALL {
88	        let crate_dir = req.out_dir.join(crate_name(&req.slug, role));
89	        let ctx = Context {
90	            slug: &req.slug,
91	            display_name: &req.display_name,
92	            type_name: &req.type_name,
93	            role,
94	            framework_path: &req.framework_path,
95	        };
96	        let mut crate_files = files(&ctx);
97	
98	        // Spec-driven overrides: when --spec is set and we're scaffolding
99	        // the -isa crate, replace the relevant module stubs with generated
100	        // code. Other crates are unchanged.
101	        if role == CrateRole::Isa
102	            && let Some(spec) = req.spec.as_ref()
103	        {
104	            apply_spec_overrides(&mut crate_files, spec, &req.type_name, &req.slug);
105	        }
106	
107	        for (rel_path, content) in crate_files {
108	            let full_path = crate_dir.join(&rel_path);
109	            if !req.force && fs.exists(&full_path) {
110	                return Err(ScaffoldError::AlreadyExists(full_path));
111	            }
112	            if let Some(parent) = full_path.parent() {
113	                fs.create_dir_all(parent)?;
114	            }
115	            fs.write(&full_path, &content)?;
116	            written.push(full_path);
117	        }
118	    }
119	    Ok(written)
120	}
121	
122	fn apply_spec_overrides(
123	    files: &mut Vec<(PathBuf, String)>,
124	    spec: &Spec,
125	    type_name: &str,
126	    slug: &str,
127	) {
128	    let overrides: Vec<(PathBuf, String)> = vec![
129	        (PathBuf::from("src/opcode.rs"), emit::opcode_rs(spec)),
130	        (PathBuf::from("src/register.rs"), emit::register_rs(spec)),
131	        (PathBuf::from("src/branch.rs"), emit::branch_rs(spec)),
132	        (PathBuf::from("src/encode.rs"), emit::encode_rs(spec)),
133	        (PathBuf::from("src/decode.rs"), emit::decode_rs(spec)),
134	        (
135	            PathBuf::from("src/lib.rs"),
136	            emit::lib_rs(spec, type_name, slug),
137	        ),
138	        (
139	            PathBuf::from("tests/roundtrip.rs"),
140	            emit::roundtrip_test(spec, type_name, slug),
141	        ),
142	    ];
143	    for (path, content) in overrides {
144	        if let Some(existing) = files.iter_mut().find(|(p, _)| *p == path) {
145	            existing.1 = content;
146	        } else {
147	            files.push((path, content));
148	        }
149	    }
150	}
