152	/// List the files that would be written, without touching the filesystem.
153	/// Used by `--dry-run`.
154	pub fn dry_run_paths(req: &ScaffoldRequest) -> Result<Vec<PathBuf>, ScaffoldError> {
155	    validate_slug(&req.slug)?;
156	    validate_type_name(&req.type_name)?;
157	    let mut out = Vec::new();
158	    for role in CrateRole::ALL {
159	        let crate_dir: &Path = &req.out_dir.join(crate_name(&req.slug, role));
160	        let ctx = Context {
161	            slug: &req.slug,
162	            display_name: &req.display_name,
163	            type_name: &req.type_name,
164	            role,
165	            framework_path: &req.framework_path,
166	        };
167	        let mut crate_files = files(&ctx);
168	        if role == CrateRole::Isa && req.spec.is_some() {
169	            // Roundtrip test is only added in spec mode.
170	            if !crate_files
171	                .iter()
172	                .any(|(p, _)| p.as_os_str() == "tests/roundtrip.rs")
173	            {
174	                crate_files.push((PathBuf::from("tests/roundtrip.rs"), String::new()));
175	            }
176	        }
177	        for (rel_path, _content) in crate_files {
178	            out.push(crate_dir.join(&rel_path));
179	        }
180	    }
181	    Ok(out)
182	}

